INSERT INTO PHIM (MaPhim, TenPhim, ThoiLuong, NgonNgu, QuocGia, DaoDien, DienVienChinh, NgayKhoiChieu, MoTaNoiDung, DoTuoi, ChuDePhim, Anh) VALUES ('PH009', 'Săn Mạng', 171, 'Japanese', 'Việt Nam', 'Christopher Nolan', 'Thái Hòa', TO_DATE('2026-04-24', 'YYYY-MM-DD'), 'Đang đau buồn, người phụ nữ nọ thử thách giới hạn trong chuyến phiêu lưu đơn độc giữa vùng hoang dã Úc, nhưng lại bị cuốn vào trò chơi méo mó của một kẻ sát nhân coi cô là con mồi.', 13, 'Viễn tưởng', 'https://image.tmdb.org/t/p/w500/jMSlZZScFPA6YqatxzrixoMlTDk.jpg');
INSERT INTO THE_LOAI_PHIM (MaPhim, TheLoai) VALUES ('PH009', 'Viễn tưởng');
INSERT INTO PHIM (MaPhim, TenPhim, ThoiLuong, NgonNgu, QuocGia, DaoDien, DienVienChinh, NgayKhoiChieu, MoTaNoiDung, DoTuoi, ChuDePhim, Anh) VALUES ('PH010', 'Phim Super Mario Thiên Hà', 158, 'Japanese', 'Japan', 'Michael Bay', 'Robert Downey Jr.', TO_DATE('2026-04-01', 'YYYY-MM-DD'), 'Nối tiếp thành công của phần phim đầu tiên, Mario và Luigi dấn thân vào một cuộc phiêu lưu ngoài sức tưởng tượng khi họ bị cuốn vào không gian sâu thẳm. Lần này, họ gặp gỡ Rosalina, người bảo vệ các vì sao và là "mẹ" của những sinh vật Luma đáng yêu. Cả nhóm phải hợp sức để ngăn chặn âm mưu thôn tính toàn bộ vũ trụ của Bowser, khi hắn đang thu thập các Grand Stars để xây dựng một đế chế thiên hà hùng mạnh. Phim hứa hẹn mang đến những màn rượt đuổi nghẹt thở giữa các hành tinh với trọng lực si...', 13, 'Siêu anh hùng', 'https://image.tmdb.org/t/p/w500/h1FlxHYiVcZVkIE5XW599ZkV6Sr.jpg');
INSERT INTO THE_LOAI_PHIM (MaPhim, TheLoai) VALUES ('PH010', 'Siêu anh hùng');
INSERT INTO PHIM (MaPhim, TenPhim, ThoiLuong, NgonNgu, QuocGia, DaoDien, DienVienChinh, NgayKhoiChieu, MoTaNoiDung, DoTuoi, ChuDePhim, Anh) VALUES ('PH011', 'Michael', 151, 'English', 'Việt Nam', 'James Cameron', 'Thái Hòa', TO_DATE('2026-04-22', 'YYYY-MM-DD'), 'Michael là bức chân dung điện ảnh khắc họa cuộc đời và di sản của một trong những nghệ sĩ có sức ảnh hưởng lớn nhất mà thế giới từng biết đến. Bộ phim kể về cuộc đời của Michael Jackson ngoài âm nhạc, theo dấu hành trình từ khi tài năng phi thường của ông được phát hiện trong vai trò giọng ca chính của nhóm Jackson Five, cho đến khi ông trở thành một nghệ sĩ có tầm nhìn xa, với khát vọng sáng tạo không ngừng để vươn tới danh hiệu “ngôi sao giải trí vĩ đại nhất thế giới”. Cho thấy cuộc sống ph...', 13, 'Hài', 'https://image.tmdb.org/t/p/w500/sXP7VzpnHQIThf5v6b64XaczEK2.jpg');
INSERT INTO THE_LOAI_PHIM (MaPhim, TheLoai) VALUES ('PH011', 'Hài');
