INSERT INTO PHIM (MaPhim, TenPhim, ThoiLuong, NgonNgu, QuocGia, DaoDien, DienVienChinh, NgayKhoiChieu, MoTaNoiDung, DoTuoi, ChuDePhim, Anh) VALUES ('PH013', 'Cứu', 112, 'English', 'UK', 'Christopher Nolan', 'Kiều Minh Tuấn', TO_DATE('2026-01-22', 'YYYY-MM-DD'), 'Hai đồng nghiệp trở thành những người sống sót duy nhất sau một vụ rơi máy bay và bị mắc kẹt trên một hòn đảo hoang. Tại đây, họ buộc phải gạt bỏ những mâu thuẫn trong quá khứ để hợp tác sinh tồn. Nhưng càng kéo dài, cuộc chiến không chỉ còn là chống chọi với thiên nhiên khắc nghiệt — mà trở thành màn đấu trí và đấu ý chí, nơi chỉ những người đủ tỉnh táo và quyết liệt mới có cơ hội thoát ra sống sót.', 16, 'Hài', 'https://image.tmdb.org/t/p/w500/hu5J1hJYToOxjceeqyXogq5nRwt.jpg');
INSERT INTO THE_LOAI_PHIM (MaPhim, TheLoai) VALUES ('PH013', 'Hài');
INSERT INTO PHIM (MaPhim, TenPhim, ThoiLuong, NgonNgu, QuocGia, DaoDien, DienVienChinh, NgayKhoiChieu, MoTaNoiDung, DoTuoi, ChuDePhim, Anh) VALUES ('PH014', 'Chúng Sẽ Đoạt Mạng', 128, 'Japanese', 'UK', 'Zack Snyder', 'Kiều Minh Tuấn', TO_DATE('2026-03-25', 'YYYY-MM-DD'), 'Nội dung đang cập nhật...', 13, 'Hành động', 'https://image.tmdb.org/t/p/w500/zde8jXxWl5Cc1DctVjhHRLOe1pn.jpg');
