INSERT INTO PHIM (MaPhim, TenPhim, ThoiLuong, NgonNgu, QuocGia, DaoDien, DienVienChinh, NgayKhoiChieu, MoTaNoiDung, DoTuoi, ChuDePhim, Anh) VALUES ('PH015', 'Avatar: Lửa và Tro Tàn', 160, 'Tiếng Việt', 'USA', 'Christopher Nolan', 'Thái Hòa', TO_DATE('2025-12-17', 'YYYY-MM-DD'), 'Sau cuộc chiến tàn khốc với RDA và nỗi mất mát to lớn khi đứa con trai cả hy sinh, Jake Sully và Neytiri phải đối mặt với một mối đe dọa mới trên Pandora: tộc Tro Tàn — một nhóm Na''vi hung bạo và khát khao quyền lực, do thủ lĩnh tàn nhẫn Varang dẫn dắt. Gia đình Jake buộc phải chiến đấu để sinh tồn và bảo vệ tương lai của Pandora, trong một cuộc xung đột đẩy họ đến giới hạn cuối cùng cả về thể xác lẫn tinh thần.', 18, 'Tình cảm', 'https://image.tmdb.org/t/p/w500/w6DBmG260sCHBQdGzkBIVn9gAQZ.jpg');
INSERT INTO THE_LOAI_PHIM (MaPhim, TheLoai) VALUES ('PH015', 'Tình cảm');
INSERT INTO PHIM (MaPhim, TenPhim, ThoiLuong, NgonNgu, QuocGia, DaoDien, DienVienChinh, NgayKhoiChieu, MoTaNoiDung, DoTuoi, ChuDePhim, Anh) VALUES ('PH016', 'Tình Yêu Đầu Đời', 110, 'Tiếng Việt', 'Korea', 'Christopher Nolan', 'Tom Cruise', TO_DATE('2000-10-27', 'YYYY-MM-DD'), 'Vào ngày nước Ý tham chiến năm 1940, có hai điều xảy ra với cậu bé 12 tuổi Renato: cậu bé có được chiếc xe đạp đầu tiên và cậu bé có cái nhìn đầu tiên về Malèna. Cô ấy là một người ngoài xinh đẹp, thầm lặng, đã chuyển đến thị trấn Sicilia này để ở với chồng của cô ấy, Nico. Anh ta nhanh chóng ra trận, để lại cô trước ánh mắt thèm muốn của những người đàn ông và những chiếc lưỡi sắc bén của phụ nữ. Trong vài năm tiếp theo, khi Renato dần trưởng thành, anh chứng kiến Malèna đau khổ và chứng tỏ ...', 18, 'Hành động', 'https://image.tmdb.org/t/p/w500/v71eH4CjbH4s0YclfTFbEhlMVCR.jpg');
INSERT INTO THE_LOAI_PHIM (MaPhim, TheLoai) VALUES ('PH016', 'Hành động');
INSERT INTO PHIM (MaPhim, TenPhim, ThoiLuong, NgonNgu, QuocGia, DaoDien, DienVienChinh, NgayKhoiChieu, MoTaNoiDung, DoTuoi, ChuDePhim, Anh) VALUES ('PH017', 'Hoppers: Cú Nhảy Kỳ Diệu', 126, 'Japanese', 'Japan', 'Lý Hải', 'Scarlett Johansson', TO_DATE('2026-03-04', 'YYYY-MM-DD'), 'Các nhà khoa học đã khám phá ra cách "nhảy" ý thức con người vào những con vật robot sống động như thật, cho phép con người giao tiếp với động vật dưới hình dạng động vật! Nhờ công nghệ mới này, Mabel sẽ khám phá những bí ẩn trong thế giới động vật vượt xa mọi điều cô từng tưởng tượng.', 13, 'Viễn tưởng', 'https://image.tmdb.org/t/p/w500/1A7WxXAYddDCrO9dTCEdSzQKU9d.jpg');
INSERT INTO THE_LOAI_PHIM (MaPhim, TheLoai) VALUES ('PH017', 'Viễn tưởng');
INSERT INTO PHIM (MaPhim, TenPhim, ThoiLuong, NgonNgu, QuocGia, DaoDien, DienVienChinh, NgayKhoiChieu, MoTaNoiDung, DoTuoi, ChuDePhim, Anh) VALUES ('PH018', 'Huyền Thoại Aang: Tiết Khí Sư Cuối Cùng', 155, 'Korean', 'USA', 'Michael Bay', 'Tom Cruise', TO_DATE('2026-10-09', 'YYYY-MM-DD'), 'Bộ phim tập trung vào giai đoạn hậu chiến tranh, khi thế giới đang trong quá trình tái thiết và đối mặt với những mối đe dọa mới tinh vi hơn từ các tàn dư chính trị. Aang phải gánh vác trọng trách duy trì sự cân bằng giữa bốn quốc gia, đồng thời đối diện với những áp lực của một Thế Thần trưởng thành. Phim hứa hẹn sẽ khai thác sâu hơn về sức mạnh của Aang ở thời kỳ đỉnh cao và mối quan hệ bền chặt của nhóm bạn sau nhiều năm gắn bó.', 13, 'Hài', 'https://image.tmdb.org/t/p/w500/gf7EeEQe22Zu1u55wRT8EAnav93.jpg');
INSERT INTO THE_LOAI_PHIM (MaPhim, TheLoai) VALUES ('PH018', 'Hài');
INSERT INTO PHIM (MaPhim, TenPhim, ThoiLuong, NgonNgu, QuocGia, DaoDien, DienVienChinh, NgayKhoiChieu, MoTaNoiDung, DoTuoi, ChuDePhim, Anh) VALUES ('PH019', 'Venganza', 157, 'Japanese', 'Japan', 'Zack Snyder', 'Tom Cruise', TO_DATE('2026-02-26', 'YYYY-MM-DD'), 'Nội dung đang cập nhật...', 13, 'Viễn tưởng', 'https://image.tmdb.org/t/p/w500/ggJGx8fwwy21gEIXYusIlHcUn8z.jpg');
