INSERT INTO PHIM (MaPhim, TenPhim, ThoiLuong, NgonNgu, QuocGia, DaoDien, DienVienChinh, NgayKhoiChieu, MoTaNoiDung, DoTuoi, ChuDePhim, Anh) VALUES ('PH020', 'Yêu Nữ Thích Hàng Hiệu', 168, 'English', 'Korea', 'Christopher Nolan', 'Scarlett Johansson', TO_DATE('2006-06-29', 'YYYY-MM-DD'), 'Một sinh viên tốt nghiệp thông minh nhưng nhạy cảm mới làm nghề trợ lý cho Miranda Priestly, tổng biên tập tạp chí thời trang cao cấp. Liệu cô ấy có thể hoàn thành công việc cho Miranda khó tính không?', 16, 'Hành động', 'https://image.tmdb.org/t/p/w500/d4nV102c3QLA5T77tjfq9tcCvmi.jpg');
INSERT INTO THE_LOAI_PHIM (MaPhim, TheLoai) VALUES ('PH020', 'Hành động');
INSERT INTO PHIM (MaPhim, TenPhim, ThoiLuong, NgonNgu, QuocGia, DaoDien, DienVienChinh, NgayKhoiChieu, MoTaNoiDung, DoTuoi, ChuDePhim, Anh) VALUES ('PH021', 'Yêu Nữ Thích Hàng Hiệu 2', 111, 'Tiếng Việt', 'Japan', 'Zack Snyder', 'Robert Downey Jr.', TO_DATE('2026-04-29', 'YYYY-MM-DD'), 'Hai mươi năm sau màn hóa thân kinh điển vào các vai diễn Miranda, Andy, Emily và Nigel — Meryl Streep, Anne Hathaway, Emily Blunt và Stanley Tucci sẽ chính thức trở lại với những con phố thời thượng của New York và văn phòng sang trọng của Tạp chí Runway trong "The Devil Wears Prada 2" (Yêu Nữ Thích Hàng Hiệu 2). Đây là phần phim tiếp theo cực kỳ được mong đợi từ 20th Century Studios, kế thừa sức hút từ hiện tượng điện ảnh năm 2006 từng định hình phong cách cho cả một thế hệ. Bộ phim được đạo...', 18, 'Hoạt hình', 'https://image.tmdb.org/t/p/w500/4qpxv3OrwOlMHumVI7Zco3zzGaF.jpg');
INSERT INTO THE_LOAI_PHIM (MaPhim, TheLoai) VALUES ('PH021', 'Hoạt hình');
INSERT INTO PHIM (MaPhim, TenPhim, ThoiLuong, NgonNgu, QuocGia, DaoDien, DienVienChinh, NgayKhoiChieu, MoTaNoiDung, DoTuoi, ChuDePhim, Anh) VALUES ('PH022', 'Kẻ Ẩn Dật', 179, 'Korean', 'UK', 'Christopher Nolan', 'Tom Cruise', TO_DATE('2026-01-28', 'YYYY-MM-DD'), 'Michael Mason, một cựu sát thủ chính phủ đang sống ẩn dật trên một hòn đảo hẻo lánh tại Scotland, tình cờ cứu mạng một cô bé tên Jessie sau một cơn bão dữ dội. Hành động nghĩa hiệp này vô tình khiến tung tích của anh bị lộ, buộc Mason phải đối đầu với những bóng ma từ quá khứ và các đặc vụ MI6 đang truy đuổi gắt gao. Để bảo vệ đứa trẻ, anh phải từ bỏ cuộc sống yên bình, vận dụng mọi kỹ năng sinh tồn và chiến đấu để thoát khỏi vòng vây của những kẻ thù nguy hiểm.', 16, 'Hoạt hình', 'https://image.tmdb.org/t/p/w500/mucESEbFFqk3ilVpNxEF53IHIVT.jpg');
INSERT INTO THE_LOAI_PHIM (MaPhim, TheLoai) VALUES ('PH022', 'Hoạt hình');
INSERT INTO PHIM (MaPhim, TenPhim, ThoiLuong, NgonNgu, QuocGia, DaoDien, DienVienChinh, NgayKhoiChieu, MoTaNoiDung, DoTuoi, ChuDePhim, Anh) VALUES ('PH023', 'Thoát Khỏi Tận Thế', 143, 'English', 'Việt Nam', 'Victor Vũ', 'Keanu Reeves', TO_DATE('2026-03-15', 'YYYY-MM-DD'), 'Mất trí nhớ và lạc lõng trên một con tàu vũ trụ, một phi hành gia khám phá ra rằng anh là hy vọng duy nhất của nhân loại trước bờ vực tuyệt chủng. Một liên minh bất ngờ được hình thành, nắm giữ vận mệnh của tất cả.', 16, 'Hài', 'https://image.tmdb.org/t/p/w500/7NzV9SN5ocWzMrdQw9fFDgLYVJC.jpg');
INSERT INTO THE_LOAI_PHIM (MaPhim, TheLoai) VALUES ('PH023', 'Hài');
INSERT INTO PHIM (MaPhim, TenPhim, ThoiLuong, NgonNgu, QuocGia, DaoDien, DienVienChinh, NgayKhoiChieu, MoTaNoiDung, DoTuoi, ChuDePhim, Anh) VALUES ('PH024', 'Tuyển Thủ Dê: "Mùi" Vị Chiến Thắng', 125, 'Tiếng Việt', 'Japan', 'Lý Hải', 'Keanu Reeves', TO_DATE('2026-02-11', 'YYYY-MM-DD'), 'Will là một chú dê nhỏ với những ước mơ lớn, người có được cơ hội duy nhất trong đời để gia nhập các vận động viên chuyên nghiệp và thi đấu môn rugebol — một môn thể thao cường độ cao, pha trộn và đối kháng toàn diện, nơi các loài động vật nhanh nhất và hung dữ nhất thế giới thống trị. Những đồng đội mới của Will không mấy hào hứng khi có một chú dê nhỏ trong đội hình, nhưng Will quyết tâm tạo nên một cuộc cách mạng cho môn thể thao này và chứng minh một lần và mãi mãi rằng: “Nhỏ bé cũng biết...', 16, 'Tình cảm', 'https://image.tmdb.org/t/p/w500/wZRJ3Q2XRJHov1SS80sTXbfjkz9.jpg');
INSERT INTO THE_LOAI_PHIM (MaPhim, TheLoai) VALUES ('PH024', 'Tình cảm');
INSERT INTO PHIM (MaPhim, TenPhim, ThoiLuong, NgonNgu, QuocGia, DaoDien, DienVienChinh, NgayKhoiChieu, MoTaNoiDung, DoTuoi, ChuDePhim, Anh) VALUES ('PH025', 'Thanh Gươm Diệt Quỷ: Vô Hạn Thành', 154, 'Korean', 'UK', 'Zack Snyder', 'Tom Cruise', TO_DATE('2025-07-18', 'YYYY-MM-DD'), 'Khi các thành viên của Sát Quỷ Đoàn và Trụ Cột tham gia vào chương trình đặc huấn để chuẩn bị cho trận chiến sắp với lũ quỷ, Kibutsuji Muzan xuất hiện tại Dinh thự Ubuyashiki. Khi thủ lĩnh của Sát Quỷ Đoàn gặp nguy hiểm, Tanjiro và các Trụ Cột trở về trụ sở Thế nhưng, Muzan bất ngờ kéo toàn bộ Sát Quỷ Đoàn đến hang ổ cuối cùng của lũ quỷ là Vô Hạn Thành, mở màn cho trận đánh cuối cùng của cả hai phe.', 13, 'Siêu anh hùng', 'https://image.tmdb.org/t/p/w500/nV99ACeAa8fFFso0tQZ3HktEf5X.jpg');
INSERT INTO THE_LOAI_PHIM (MaPhim, TheLoai) VALUES ('PH025', 'Siêu anh hùng');
INSERT INTO PHIM (MaPhim, TenPhim, ThoiLuong, NgonNgu, QuocGia, DaoDien, DienVienChinh, NgayKhoiChieu, MoTaNoiDung, DoTuoi, ChuDePhim, Anh) VALUES ('PH026', 'The Crucifix: Blood of the Exorcist', 123, 'English', 'Japan', 'Victor Vũ', 'Kiều Minh Tuấn', TO_DATE('2025-01-09', 'YYYY-MM-DD'), 'Nội dung đang cập nhật...', 18, 'Kinh dị', 'https://image.tmdb.org/t/p/w500/u3qOxvlykoTpurg1G8VOcawoePI.jpg');
INSERT INTO THE_LOAI_PHIM (MaPhim, TheLoai) VALUES ('PH026', 'Kinh dị');
INSERT INTO PHIM (MaPhim, TenPhim, ThoiLuong, NgonNgu, QuocGia, DaoDien, DienVienChinh, NgayKhoiChieu, MoTaNoiDung, DoTuoi, ChuDePhim, Anh) VALUES ('PH027', 'Tội Phạm 101', 99, 'English', 'UK', 'Trấn Thành', 'Kiều Minh Tuấn', TO_DATE('2026-02-11', 'YYYY-MM-DD'), 'Lấy bối cảnh thành phố Los Angeles đầy nắng và bụi đường, Tội Phạm 101 kể về một tên trộm nữ trang bí ẩn (Chris Hemsworth) với hàng loạt phi vụ táo bạo khiến cảnh sát phải đau đầu. Trong lúc chuẩn bị cho phi vụ lớn nhất của mình, hắn gặp gỡ một nữ nhân viên bảo hiểm (Halle Berry), người cũng đang vật lộn với những lựa chọn trong đời mình. Trong khi đó, một thanh tra (Mark Ruffalo) đã tìm ra quy luật trong chuỗi các vụ án và đang ráo riết truy đuổi tên trộm, khiến cuộc chơi trở nên căng thẳng ...', 13, 'Kinh dị', 'https://image.tmdb.org/t/p/w500/2i7DfVMYX7DyjmQiX64Le8uK45K.jpg');
INSERT INTO THE_LOAI_PHIM (MaPhim, TheLoai) VALUES ('PH027', 'Kinh dị');
INSERT INTO PHIM (MaPhim, TenPhim, ThoiLuong, NgonNgu, QuocGia, DaoDien, DienVienChinh, NgayKhoiChieu, MoTaNoiDung, DoTuoi, ChuDePhim, Anh) VALUES ('PH028', 'Phi Vụ Động Trời 2', 157, 'English', 'USA', 'James Cameron', 'Robert Downey Jr.', TO_DATE('2025-11-26', 'YYYY-MM-DD'), 'Trong bộ phim "Zootopia 2 - Phi Vụ Động Trời 2" từ Walt Disney Animation Studios, hai thám tử Judy Hopps (lồng tiếng bởi Ginnifer Goodwin) và Nick Wilde (lồng tiếng bởi Jason Bateman) bước vào hành trình truy tìm một sinh vật bò sát bí ẩn vừa xuất hiện tại Zootopia và khiến cả vương quốc động vật bị đảo lộn. Để phá được vụ án, Judy và Nick buộc phải hoạt động bí mật tại những khu vực mới lạ của thành phố – nơi mối quan hệ đồng nghiệp của họ bị thử thách hơn bao giờ hết.', 18, 'Tình cảm', 'https://image.tmdb.org/t/p/w500/5wXpOF9WPUKliIzNBdAqwAStLHU.jpg');
INSERT INTO THE_LOAI_PHIM (MaPhim, TheLoai) VALUES ('PH028', 'Tình cảm');
INSERT INTO PHIM (MaPhim, TenPhim, ThoiLuong, NgonNgu, QuocGia, DaoDien, DienVienChinh, NgayKhoiChieu, MoTaNoiDung, DoTuoi, ChuDePhim, Anh) VALUES ('PH029', 'Trợ lý nhà xác', 152, 'Tiếng Việt', 'Japan', 'Christopher Nolan', 'Tom Cruise', TO_DATE('2026-02-13', 'YYYY-MM-DD'), 'Rebecca Owens, một sinh viên mới tốt nghiệp ngành khoa học nhà xác, nhận công việc ca đêm tại nhà xác River Fields. Ban đầu, công việc có vẻ đơn giản — ướp xác, hoàn thành giấy tờ và giữ gìn vệ sinh. Nhưng khi Rebecca bắt đầu làm ca đêm, mọi chuyện bắt đầu trở nên tăm tối.', 18, 'Tình cảm', 'https://image.tmdb.org/t/p/w500/72AoFPC5TY4DfJwXXS9rPwPeReD.jpg');
