INSERT INTO PHIM (MaPhim, TenPhim, ThoiLuong, NgonNgu, QuocGia, DaoDien, DienVienChinh, NgayKhoiChieu, MoTaNoiDung, DoTuoi, ChuDePhim, Anh) VALUES ('PH044', 'Tiếng Thét 7', 170, 'Korean', 'Korea', 'Michael Bay', 'Robert Downey Jr.', TO_DATE('2026-02-25', 'YYYY-MM-DD'), 'Sidney Evans (Neve Campbell), nạn nhân sống sót của một vụ thảm sát nhiều năm trước, giờ đang sống hạnh phúc cùng chồng và con gái ở một thị trấn khác thì tên sát nhân Ghostface mới lại xuất hiện. Những nỗi sợ hãi đen tối nhất của cô trở thành hiện thực khi con gái cô Tatum Evans (Isabel May) trở thành mục tiêu tiếp theo. Quyết tâm bảo vệ gia đình, Sidney buộc phải đối mặt với những kinh hoàng trong quá khứ để chấm dứt cuộc đổ máu một lần và mãi mãi.', 13, 'Siêu anh hùng', 'https://image.tmdb.org/t/p/w500/nXXpliMy4Y0mwRa4OlhOb6GyOEE.jpg');
INSERT INTO THE_LOAI_PHIM (MaPhim, TheLoai) VALUES ('PH044', 'Siêu anh hùng');
INSERT INTO PHIM (MaPhim, TenPhim, ThoiLuong, NgonNgu, QuocGia, DaoDien, DienVienChinh, NgayKhoiChieu, MoTaNoiDung, DoTuoi, ChuDePhim, Anh) VALUES ('PH045', 'Một bộ phim của Lee Cronin: Xác ướp', 97, 'Japanese', 'UK', 'Zack Snyder', 'Scarlett Johansson', TO_DATE('2026-04-15', 'YYYY-MM-DD'), 'Con gái nhỏ của một nhà báo biến mất không dấu vết giữa sa mạc. Tám năm sau, gia đình tan vỡ của họ bàng hoàng khi cô bé bất ngờ được đưa trở về — nhưng cuộc đoàn tụ tưởng chừng hạnh phúc nhanh chóng biến thành một cơn ác mộng sống.', 13, 'Hoạt hình', 'https://image.tmdb.org/t/p/w500/fIbu9GsLv7j8uWA8OiAEtpNEDsZ.jpg');
INSERT INTO THE_LOAI_PHIM (MaPhim, TheLoai) VALUES ('PH045', 'Hoạt hình');
INSERT INTO PHIM (MaPhim, TenPhim, ThoiLuong, NgonNgu, QuocGia, DaoDien, DienVienChinh, NgayKhoiChieu, MoTaNoiDung, DoTuoi, ChuDePhim, Anh) VALUES ('PH046', 'Hố Đen Tử Thần', 108, 'Korean', 'Korea', 'Michael Bay', 'Thái Hòa', TO_DATE('2014-11-05', 'YYYY-MM-DD'), 'Interstellar nói về chuyến hành trình đi tìm một hành tinh mới cho loài người trú ngụ khi mà Trái Đất dần dần không còn là nơi an toàn và sự sống thì đang chết dần với những dịch bệnh trên các loại cây lương thực, đe dọa đến sự tồn tại của loài người một cách mạnh mẽ. Chúng ta sẽ đi theo hành trình của phi hành đoàn gồm Copper, Amelia cùng các thành viên khác trong việc giải cứu các phi hành gia khác đã lên đường khám phá các hành tinh mới để tìm ra hành tinh mới cho loài người trú ngụ', 16, 'Siêu anh hùng', 'https://image.tmdb.org/t/p/w500/if4TI9LbqNIrzkoOgWjX5PZYDYe.jpg');
INSERT INTO THE_LOAI_PHIM (MaPhim, TheLoai) VALUES ('PH046', 'Siêu anh hùng');
INSERT INTO PHIM (MaPhim, TenPhim, ThoiLuong, NgonNgu, QuocGia, DaoDien, DienVienChinh, NgayKhoiChieu, MoTaNoiDung, DoTuoi, ChuDePhim, Anh) VALUES ('PH047', 'Cuộc Chiến Giữa Các Thế Giới', 128, 'Tiếng Việt', 'Korea', 'Victor Vũ', 'Robert Downey Jr.', TO_DATE('2025-07-29', 'YYYY-MM-DD'), 'Will Radford — chuyên gia phân tích an ninh mạng hàng đầu của Bộ An ninh Nội địa — chuyên theo dõi các mối đe dọa đến an ninh quốc gia thông qua một chương trình giám sát diện rộng. Nhưng một cuộc tấn công bất ngờ từ một thực thể bí ẩn đã khiến anh bắt đầu nghi ngờ: phải chăng chính phủ đang che giấu điều gì đó… không chỉ với anh mà với toàn thế giới?', 13, 'Hành động', 'https://image.tmdb.org/t/p/w500/3e6GQvCA9hguxqfqA75BDvG7Vvp.jpg');
